enum WalletFeature {
  coinControl(
    "Coin control",
    "Control, freeze, and utilize outputs at your discretion",
  ),
  masternodes("Masternodes", "Create, start and follow your masternodes"),
  coldStaking(
    "Cold staking",
    "Delegate coins to a staker and earn rewards while they stay yours",
  ),
  governance(
    "Governance",
    "Budget proposals: follow them and vote with your masternodes",
  ),
  privatize(
    "Privatize funds",
    "Move your whole transparent balance to your shield balance",
  ),

  // special cases
  reuseAddress("", "");

  final String label;
  final String description;
  const WalletFeature(this.label, this.description);
}

/// A feature's icon: an SVG asset path or a Material [IconData].
Widget walletFeatureIcon(Object icon, double size, Color color) =>
    icon is IconData
    ? Icon(icon, size: size, color: color)
    : SvgPicture.asset(icon as String, width: size, height: size, color: color);

class DesktopWalletFeatures extends ConsumerStatefulWidget {
  const DesktopWalletFeatures({super.key, required this.walletId});

  final String walletId;

  @override
  ConsumerState<DesktopWalletFeatures> createState() =>
      _DesktopWalletFeaturesState();
}

class _DesktopWalletFeaturesState extends ConsumerState<DesktopWalletFeatures> {
  Future<void> _onMorePressed(
    List<(WalletFeature, Object, FutureOr<void> Function())> options,
  ) async {
    await showDialog<void>(
      context: context,
      builder: (_) =>
          MoreFeaturesDialog(walletId: widget.walletId, options: options),
    );
  }

  void _push(String route) =>
      Navigator.of(context).pushNamed(route, arguments: widget.walletId);

  void _onCoinControlPressed() {
    // PIVX: the coin control that also covers shield notes.
    if (ref.read(pWallets).getWallet(widget.walletId) is PivxWallet) {
      Navigator.of(context).pushNamed(
        CoinControlView.routeName,
        arguments: Tuple2(widget.walletId, CoinControlViewType.manage),
      );
      return;
    }
    Navigator.of(
      context,
    ).pushNamed(DesktopCoinControlView.routeName, arguments: widget.walletId);
  }

  /// PIVX: shield the whole transparent balance, after a confirmation.
  Future<void> _onPrivatizePressed() async {
    final wallet = ref.read(pWallets).getWallet(widget.walletId);
    if (wallet is! PivxWallet) return;
    if (wallet.info.cachedBalance.spendable <= Amount.zero) {
      unawaited(
        showFloatingFlushBar(
          type: FlushBarType.info,
          message: "No funds available to privatize!",
          context: context,
        ),
      );
      return;
    }
    final confirmed = await showDialog<bool>(
      context: context,
      builder: (context) => DesktopDialog(
        maxWidth: 450,
        maxHeight: double.infinity,
        child: Padding(
          padding: const EdgeInsets.only(left: 32, bottom: 32),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Row(
                mainAxisAlignment: MainAxisAlignment.spaceBetween,
                children: [
                  Text("Attention!", style: STextStyles.desktopH3(context)),
                  const DesktopDialogCloseButton(),
                ],
              ),
              const SizedBox(height: 12),
              Padding(
                padding: const EdgeInsets.only(right: 32),
                child: Text(
                  "You're about to privatize all of your public funds.",
                  style: STextStyles.desktopTextExtraExtraSmall(context)
                      .copyWith(fontSize: 18),
                ),
              ),
              const SizedBox(height: 40),
              Padding(
                padding: const EdgeInsets.only(right: 32),
                child: Row(
                  children: [
                    Expanded(
                      child: SecondaryButton(
                        buttonHeight: ButtonHeight.l,
                        label: "Cancel",
                        onPressed: () => Navigator.of(context).pop(false),
                      ),
                    ),
                    const SizedBox(width: 16),
                    Expanded(
                      child: PrimaryButton(
                        buttonHeight: ButtonHeight.l,
                        label: "Continue",
                        onPressed: () => Navigator.of(context).pop(true),
                      ),
                    ),
                  ],
                ),
              ),
            ],
          ),
        ),
      ),
    );
    if (confirmed != true || !mounted) return;
    Exception? error;
    await showLoading<void>(
      whileFuture: wallet.shieldAllTransparent(),
      context: context,
      message: "Anonymizing balance",
      onException: (e) => error = e,
    );
    if (!mounted) return;
    unawaited(
      showFloatingFlushBar(
        type: error == null ? FlushBarType.success : FlushBarType.warning,
        message: error == null
            ? "Privatize transaction submitted"
            : "Privatize all failed: $error",
        context: context,
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final wallet = ref.watch(pWallets).getWallet(widget.walletId);

    final showCoinControl =
        wallet is CoinControlInterface &&
        ref.watch(
          prefsChangeNotifierProvider.select(
            (value) => value.enableCoinControl,
          ),
        );

    final isViewOnly = wallet is ViewOnlyOptionInterface && wallet.isViewOnly;

    // On the bar: governance and masternodes; the rest is under More.
    final options = <(WalletFeature, Object, FutureOr<void> Function())>[
      if (wallet is PivxWallet)
        (
          WalletFeature.governance,
          Icons.how_to_vote_rounded,
          () => _push(PivxGovernanceView.routeName),
        ),
      if (wallet is PivxWallet && !isViewOnly)
        (
          WalletFeature.masternodes,
          Icons.dns_rounded,
          () => _push(PivxMasternodesView.routeName),
        ),
    ];

    final moreOptions = <(WalletFeature, Object, FutureOr<void> Function())>[
      if (wallet is PivxWallet)
        (
          WalletFeature.coldStaking,
          Icons.ac_unit_rounded,
          () => _push(PivxColdStakingView.routeName),
        ),
      if (wallet is PivxWallet && wallet.supportsShield && !isViewOnly)
        (WalletFeature.privatize, Icons.shield_rounded, _onPrivatizePressed),
      if (showCoinControl)
        (WalletFeature.coinControl, Icons.checklist_rtl, _onCoinControlPressed),
    ];

    final canGen =
        !(isViewOnly &&
            wallet.viewOnlyType == ViewOnlyWalletType.addressOnly) &&
        wallet is MultiAddressInterface;

    final extraOptions = <(WalletFeature, Object, FutureOr<void> Function())>[
      if (canGen) (WalletFeature.reuseAddress, Assets.svg.key, () => ()),
    ];

    return StaticOverflowRow(
      forcedOverflow: moreOptions.isNotEmpty || extraOptions.isNotEmpty,
      overflowBuilder: (count) {
        return Padding(
          padding: const EdgeInsets.only(left: 16),
          child: SecondaryButton(
            label: "More",
            padding: const EdgeInsets.symmetric(horizontal: 16),
            buttonHeight: ButtonHeight.l,
            icon: SvgPicture.asset(
              Assets.svg.bars,
              height: 20,
              width: 20,
              color: Theme.of(context)
                  .extension<StackColors>()!
                  .buttonTextSecondary,
            ),
            onPressed: () => _onMorePressed([
              ...options.sublist(options.length - count),
              ...moreOptions,
              ...extraOptions,
            ]),
          ),
        );
      },

      children: options
          .map(
            (option) => Padding(
              padding: const EdgeInsets.only(left: 16),
              child: SecondaryButton(
                label: option.$1.label,
                padding: const EdgeInsets.symmetric(horizontal: 16),
                buttonHeight: ButtonHeight.l,
                icon: walletFeatureIcon(
                  option.$2,
                  20,
                  Theme.of(context)
                      .extension<StackColors>()!
                      .buttonTextSecondary,
                ),
                onPressed: () => option.$3(),
              ),
            ),
          )
          .toList(growable: false),
    );
  }
}
